import numpy as np
SPEC=dict(T=300.0,d=100e-9,Eg=1.4,Phi=0.25,mu_n=2e-8,mu_p=2e-8,eps_r=3.5,Nc=1e26,Nv=1e26,Gex=1e28,gamma=1.0)
def _fx_derived_constants(spec):
    _Q=1.602176634e-19; _KB=1.380649e-23; _EPS0=8.8541878128e-12
    if not isinstance(spec, dict) or 'Eg' not in spec:
        raise ValueError('spec must be the declared device configuration')
    if spec['T'] <= 0.0:
        raise ValueError('the temperature must be positive')
    VT = _KB * spec['T'] / _Q
    return dict(VT=VT, Vbi=spec['Eg'] - 2.0 * spec['Phi'], beta_L=_Q * (spec['mu_n'] + spec['mu_p']) / (spec['eps_r'] * _EPS0), ni2=spec['Nc'] * spec['Nv'] * np.exp(-spec['Eg'] / VT), eps=spec['eps_r'] * _EPS0)
def _fx_contact_densities(spec):
    if spec['Phi'] < 0.0 or spec['Phi'] > spec['Eg']:
        raise ValueError('the injection barrier must lie inside the transport gap')
    c = _fx_derived_constants(spec)
    p_an = spec['Nv'] * np.exp(-spec['Phi'] / c['VT'])
    n_cat = spec['Nc'] * np.exp(-spec['Phi'] / c['VT'])
    return np.array([c['ni2'] / p_an, p_an, n_cat, c['ni2'] / n_cat])
def start(sp,V,N):
    c=_fx_derived_constants(sp); bc=_fx_contact_densities(sp)
    return (np.linspace(0.0,c['Vbi']-V,N),np.linspace(bc[0],bc[2],N),np.linspace(bc[1],bc[3],N))
psi,n,p=start(SPEC,0.0,41)
assert np.allclose(poisson_step(psi,n,p,SPEC,0.0), target)

